{
  "claims": [
    {
      "claim_text": "In WAL mode writers do not block readers and readers do not block writers.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states this directly.",
      "citations": [
        {"index": 6, "quote": "The second advantage of WAL-mode is that writers do not block readers and readers do not block writers."}
      ]
    },
    {
      "claim_text": "A read query against a WAL database never returns SQLITE_BUSY.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 6 says there are obscure cases where a query can return SQLITE_BUSY, and passages 7-9 give cases where queries return SQLITE_BUSY.",
      "citations": [
        {"index": 6, "quote": "But there are some obscure cases where a query against a WAL-mode database can return SQLITE_BUSY, so applications should be prepared for that happenstance."},
        {"index": 7, "quote": "If another database connection has the database mode open in exclusive locking mode then all queries against the database will return SQLITE_BUSY."}
      ]
    },
    {
      "claim_text": "If another connection has the database open in exclusive locking mode, all queries against it return SQLITE_BUSY.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states this directly.",
      "citations": [
        {"index": 7, "quote": "If another database connection has the database mode open in exclusive locking mode then all queries against the database will return SQLITE_BUSY."}
      ]
    },
    {
      "claim_text": "Chrome and Firefox open their database files in exclusive locking mode.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states this directly.",
      "citations": [
        {"index": 7, "quote": "Both Chrome and Firefox open their database files in exclusive locking mode"}
      ]
    },
    {
      "claim_text": "Firefox keeps its browsing history in a SQLite file called places.sqlite.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage mentions places.sqlite or Firefox browsing history.",
      "citations": []
    },
    {
      "claim_text": "Once a connection has set EXCLUSIVE locking before its first WAL access, it can switch back with PRAGMA locking_mode=NORMAL.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 says attempts to change the locking mode with PRAGMA locking_mode=NORMAL are no-ops in this case; the only way out is to first change out of WAL journal mode.",
      "citations": [
        {"index": 4, "quote": "attempts to change the locking mode using \"PRAGMA locking_mode=NORMAL;\" are no-ops. The only way to change out of EXCLUSIVE locking mode is to first change out of WAL journal mode."}
      ]
    },
    {
      "claim_text": "If the last connection crashed, the next connection to open the database runs a recovery process while holding an exclusive lock.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 9 states this directly.",
      "citations": [
        {"index": 9, "quote": "If the last connection to a database crashed, then the first new connection to open the database will start a recovery process. An exclusive lock is held during recovery."}
      ]
    },
    {
      "claim_text": "For a database that will only be accessed by threads within a single process, a custom VFS can put the wal-index in heap memory instead of shared memory.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states this directly.",
      "citations": [
        {"index": 2, "quote": "if it is known that a particular database will only be accessed by threads within a single process, the wal-index can be implemented using heap memory instead of true shared memory."}
      ]
    },
    {
      "claim_text": "Exclusive locking mode also makes checkpoints run faster.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage discusses checkpoint speed or exclusive locking mode affecting checkpoint performance.",
      "citations": []
    }
  ]
}
